for arg in "$@"; do
  case "$arg" in
    --mode=greenfield) MODE="greenfield" ;;
    --mode=brownfield) MODE="brownfield" ;;
    --migrate) MIGRATE=true ;;
    --update) UPDATE=true ;;
    *)
      echo "Argumento desconocido: $arg" >&2
      echo "Uso: install.sh --mode=greenfield|brownfield [--migrate] | install.sh --update" >&2
      exit 1
      ;;
  esac
