# --- safe_copy: nunca pisa un archivo que ya existe ---
safe_copy() {
  local src="$1" dst="$2"
  if [ -e "$dst" ]; then
    echo "  [skip] ya existe: $dst"
  else
        mkdir -p "$(dirname "$new_path")"
    cp "$src" "$dst"
    echo "  [ok]   creado: $dst"
